#!/usr/bin/env python3
"""Pin sibling default branches to full SHAs.

``--write`` reads only ``git ls-remote`` of each sibling's default branch.
``--resolve`` and ``--github-output`` read ``ci/siblings.lock`` and do not
touch the network. Workflows checkout the emitted SHA. They do not use a
branch name.
"""

from __future__ import annotations

import argparse
import subprocess
import sys
from pathlib import Path

OWNER = "onesyue"
REF = "refs/heads/master"
REPOS = (
    "yue-node",
    "yueboard",
    "yuelink",
    "yuelink-ci",
    "yueops",
    "yueto",
)
HEADER = (
    "# Generated by scripts/update-siblings-lock.py. "
    "Full SHA of each sibling default branch."
)
ROOT = Path(__file__).resolve().parents[1]
DEFAULT_LOCK = ROOT / "ci" / "siblings.lock"


def output_key(repo: str) -> str:
    """GitHub Actions output name for one sibling. Hyphens break ``outputs.name``."""
    name = repo.split("/", 1)[1] if repo.startswith(OWNER + "/") else repo
    if name not in REPOS:
        raise ValueError(f"unknown sibling {repo}")
    return name.replace("-", "_")


def remote_argv(repo: str) -> list[str]:
    if repo not in REPOS:
        raise ValueError(f"unknown sibling {repo}")
    return ["git", "ls-remote", f"https://github.com/{OWNER}/{repo}.git", REF]


def render(pins: dict[str, str]) -> str:
    if set(pins) != set(REPOS):
        raise ValueError("sibling lock must name exactly the sibling set")
    lines = [HEADER]
    for repo in REPOS:
        sha = pins[repo]
        if len(sha) != 40 or sha.lower() != sha or any(c not in "0123456789abcdef" for c in sha):
            raise ValueError(f"sibling SHA for {repo} must be 40 lowercase hex")
        lines.append(f"{OWNER}/{repo} {sha}")
    return "\n".join(lines) + "\n"


def load_lock(path: Path) -> dict[str, str]:
    pins: dict[str, str] = {}
    text = path.read_text(encoding="utf-8")
    if "\r" in text or not text.endswith("\n"):
        raise ValueError("sibling lock must be LF and end with a newline")
    for line_number, line in enumerate(text.splitlines(), start=1):
        if not line or line.startswith("#"):
            continue
        full, separator, sha = line.partition(" ")
        prefix = OWNER + "/"
        if separator != " " or not full.startswith(prefix) or "/" in full[len(prefix):]:
            raise ValueError(f"sibling lock line {line_number} is not 'onesyue/<repo> <sha>'")
        repo = full[len(prefix):]
        if repo not in REPOS or repo in pins:
            raise ValueError(f"sibling lock line {line_number} names {repo}")
        if len(sha) != 40 or sha.lower() != sha or any(c not in "0123456789abcdef" for c in sha):
            raise ValueError(f"sibling lock line {line_number} SHA is not 40 lowercase hex")
        pins[repo] = sha
    if set(pins) != set(REPOS):
        missing = [repo for repo in REPOS if repo not in pins]
        raise ValueError("sibling lock is missing " + ", ".join(missing))
    return pins


def github_output(pins: dict[str, str]) -> str:
    return "".join(f"{output_key(repo)}={pins[repo]}\n" for repo in REPOS)


def _ls_remote(repo: str) -> str:
    proc = subprocess.run(
        remote_argv(repo),
        check=False,
        capture_output=True,
        text=True,
        timeout=30,
    )
    if proc.returncode != 0:
        raise RuntimeError(f"ls-remote failed for {OWNER}/{repo}")
    lines = [line for line in proc.stdout.splitlines() if line.strip()]
    if len(lines) != 1:
        raise RuntimeError(f"ls-remote returned {len(lines)} lines for {OWNER}/{repo}")
    sha, separator, ref = lines[0].partition("\t")
    if separator != "\t" or ref != REF or len(sha) != 40 or sha.lower() != sha:
        raise RuntimeError(f"ls-remote returned an unexpected line for {OWNER}/{repo}")
    if any(c not in "0123456789abcdef" for c in sha):
        raise RuntimeError(f"ls-remote returned an unexpected line for {OWNER}/{repo}")
    return sha


def write_lock(path: Path) -> None:
    pins = {repo: _ls_remote(repo) for repo in REPOS}
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(render(pins), encoding="utf-8")
    temporary.replace(path)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--write", action="store_true", help="refresh the lock from git ls-remote")
    mode.add_argument("--github-output", action="store_true", help="print key=sha lines from the lock")
    mode.add_argument("--resolve", metavar="REPO", help="print one lock SHA")
    parser.add_argument("--lock", type=Path, default=DEFAULT_LOCK)
    args = parser.parse_args(argv)
    if args.write:
        write_lock(args.lock)
        return 0
    pins = load_lock(args.lock)
    if args.github_output:
        sys.stdout.write(github_output(pins))
        return 0
    repo = args.resolve
    if repo.startswith(OWNER + "/"):
        repo = repo.split("/", 1)[1]
    if repo not in pins:
        raise ValueError(f"unknown sibling {args.resolve}")
    sys.stdout.write(pins[repo] + "\n")
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (OSError, RuntimeError, ValueError) as exc:
        print(f"update-siblings-lock: {exc}", file=sys.stderr)
        raise SystemExit(1) from None
